// ===== Configuração (preencha no seu n8n; nunca no repositório) =====
const URL_VALIDACAO = 'https://exemplo.com/webhook/validar';  // o QR aponta para URL_VALIDACAO?id=<id>
const COR = '#000000';  // opcional: cor dos módulos (escura, para os leitores lerem bem)
// Opcional: logo no meio, como "LARGURAxALTURA:COR1,COR2:base64" (2 bits por ponto:
// 0 branco, 1 COR1, 2 COR2). Com logo, o QR usa a correção mais alta (H, até 30%).
const LOGO = '';
