// QR code (modo byte, correção M ou H, versões 1 a 10) e PNG sem bibliotecas: o Slides
// busca esta imagem pela URL e nenhum serviço de fora vê os IDs. Só aceita IDs no
// formato e só gera o endereço de validação, nunca um texto qualquer.
const id = String(($input.first().json.query || {}).id || '');
