  const r = Array(grau).fill(0); r[grau - 1] = 1; let raiz = 1;
  for (let i = 0; i < grau; i++) {
    for (let j = 0; j < grau; j++) { r[j] = mul(r[j], raiz); if (j + 1 < grau) r[j] ^= r[j + 1]; }
    raiz = mul(raiz, 0x02);
  }
  return r;
}
