  const r = Array(div.length).fill(0);
  for (const b of msg) { const f = b ^ r.shift(); r.push(0); div.forEach((c, i) => { r[i] ^= mul(c, f); }); }
  return r;
}
const nb = BLOCOS[ver], ne = ECC[ver], palavras = Math.floor(brutos(ver) / 8);
const curtos = nb - palavras % nb, tamCurto = Math.floor(palavras / nb), div = divisor(ne);
const blocos = [];
for (let i = 0, k = 0; i < nb; i++) {
  const d = dados.slice(k, k + tamCurto - ne + (i < curtos ? 0 : 1)); k += d.length;
  const e = resto(d, div); if (i < curtos) d.push(0); blocos.push(d.concat(e));
}
const final = [];
for (let i = 0; i < blocos[0].length; i++) {
  blocos.forEach((b, j) => { if (i !== tamCurto - ne || j >= curtos) final.push(b[i]); });
}

// Matriz: padrões fixos, dados, máscara com menor penalidade.
const n = ver * 4 + 17;
const mod = Array.from({ length: n }, () => Array(n).fill(false));
const fixo = Array.from({ length: n }, () => Array(n).fill(false));
const poeFixo = (x, y, v) => { mod[y][x] = v; fixo[y][x] = true; };
for (let i = 0; i < n; i++) { poeFixo(6, i, i % 2 === 0); poeFixo(i, 6, i % 2 === 0); }
for (const [cx, cy] of [[3, 3], [n - 4, 3], [3, n - 4]]) {
  for (let dy = -4; dy <= 4; dy++) for (let dx = -4; dx <= 4; dx++) {
    const x = cx + dx, y = cy + dy, d = Math.max(Math.abs(dx), Math.abs(dy));
    if (x >= 0 && x < n && y >= 0 && y < n) poeFixo(x, y, d !== 2 && d !== 4);
  }
}
