  for (let i = 9; i < 15; i++) poeFixo(14 - i, 8, bit(i));
  for (let i = 0; i < 8; i++) poeFixo(n - 1 - i, 8, bit(i));
  for (let i = 8; i < 15; i++) poeFixo(8, n - 15 + i, bit(i));
