formato(0);
if (ver >= 7) {
  let r = ver;
  for (let i = 0; i < 12; i++) r = (r << 1) ^ ((r >>> 11) * 0x1F25);
  const b = (ver << 12) | r;
  for (let i = 0; i < 18; i++) { const v = ((b >>> i) & 1) === 1, a = n - 11 + i % 3, c = Math.floor(i / 3); poeFixo(a, c, v); poeFixo(c, a, v); }
}
let i = 0;
for (let dir = n - 1; dir >= 1; dir -= 2) {
  if (dir === 6) dir = 5;
  for (let v = 0; v < n; v++) for (let j = 0; j < 2; j++) {
    const x = dir - j, y = ((dir + 1) & 2) === 0 ? n - 1 - v : v;
    if (!fixo[y][x] && i < final.length * 8) { mod[y][x] = ((final[i >>> 3] >>> (7 - (i & 7))) & 1) === 1; i++; }
  }
}
const MASCARAS = [(x, y) => (x + y) % 2 === 0, (x, y) => y % 2 === 0, x => x % 3 === 0, (x, y) => (x + y) % 3 === 0,
  (x, y) => (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0, (x, y) => x * y % 2 + x * y % 3 === 0,
  (x, y) => (x * y % 2 + x * y % 3) % 2 === 0, (x, y) => ((x + y) % 2 + x * y % 3) % 2 === 0];
const aplica = m => { for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) if (!fixo[y][x] && MASCARAS[m](x, y)) mod[y][x] = !mod[y][x]; };
function penalidade() {  // regras 1, 2 e 4 da norma (a 3 só melhora a leitura, não é obrigatória)
  let p = 0, escuros = 0;
  for (let a = 0; a < n; a++) for (const lin of [true, false]) {
    let run = 1;
    for (let b = 1; b <= n; b++) {
      const igual = b < n && (lin ? mod[a][b] === mod[a][b - 1] : mod[b][a] === mod[b - 1][a]);
      if (igual) run++; else { if (run >= 5) p += run - 2; run = 1; }
    }
  }
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    if (mod[y][x]) escuros++;
    if (x < n - 1 && y < n - 1 && mod[y][x] === mod[y][x + 1] && mod[y][x] === mod[y + 1][x] && mod[y][x] === mod[y + 1][x + 1]) p += 3;
  }
  return p + Math.floor(Math.abs(escuros * 20 - n * n * 10) / (n * n)) * 10;
}
let melhor = 0, menor = Infinity;
for (let m = 0; m < 8; m++) { aplica(m); formato(m); const p = penalidade(); if (p < menor) { menor = p; melhor = m; } aplica(m); }
aplica(melhor); formato(melhor);

// Logo: área branca no centro (os módulos ali se perdem; a correção H recupera) e o desenho por cima.
let logo = null;
if (H) {
  const [tam, cores, dadosLogo] = LOGO.split(':');
  const [lw, lh] = tam.split('x').map(Number), px = Buffer.from(dadosLogo, 'base64');
  const alt = Math.round(n * 0.26), larg = Math.round(alt * lw / lh);  // ~26% da altura: cerca de 5% da área
  logo = { lw, lh, px, cores: cores.split(','), larg, alt, x0: Math.floor((n - larg) / 2), y0: Math.floor((n - alt) / 2) };
}
// PNG de 2 bits com paleta (fundo branco, módulos na COR, cores do logo), 10 px por módulo e a margem branca de 4 módulos da norma.
const ESC = 10, MARGEM = 4, lado = (n + 2 * MARGEM) * ESC, porLinha = Math.ceil(lado / 4);
const cru = Buffer.alloc((porLinha + 1) * lado);
for (let y = 0; y < lado; y++) for (let x = 0; x < lado; x++) {
  const mx = Math.floor(x / ESC) - MARGEM, my = Math.floor(y / ESC) - MARGEM;
  let cor = mx >= 0 && my >= 0 && mx < n && my < n && mod[my][mx] ? 1 : 0;
  if (logo && mx >= logo.x0 - 1 && mx <= logo.x0 + logo.larg && my >= logo.y0 - 1 && my <= logo.y0 + logo.alt) {
    const lx = x / ESC - MARGEM - logo.x0, ly = y / ESC - MARGEM - logo.y0;  // em módulos, dentro do logo
    cor = 0;
    if (lx >= 0 && ly >= 0 && lx < logo.larg && ly < logo.alt) {
      const k = Math.floor(ly / logo.alt * logo.lh) * logo.lw + Math.floor(lx / logo.larg * logo.lw);
      const v = (logo.px[k >> 2] >> (6 - 2 * (k & 3))) & 3;
      if (v) cor = v + 1;
    }
  }
  cru[y * (porLinha + 1) + 1 + (x >> 2)] |= cor << (6 - 2 * (x & 3));
}
const crcTab = Array.from({ length: 256 }, (_, k) => { let c = k; for (let j = 0; j < 8; j++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; return c >>> 0; });
