const pedaco = (tipo, dadosPedaco) => {
  const t = Buffer.concat([Buffer.from(tipo, 'ascii'), dadosPedaco]);
  return Buffer.concat([u32(dadosPedaco.length), t, u32(crc(t))]);
};
const zlib = [Buffer.from([0x78, 0x01])];  // deflate sem compressão, em blocos de até 65535
for (let k = 0; k < cru.length; k += 65535) {
  const parte = cru.subarray(k, k + 65535), ultimo = k + 65535 >= cru.length ? 1 : 0;
  zlib.push(Buffer.from([ultimo, parte.length & 0xFF, parte.length >> 8, ~parte.length & 0xFF, (~parte.length >> 8) & 0xFF]), parte);
}
let a1 = 1, a2 = 0;
for (const b of cru) { a1 = (a1 + b) % 65521; a2 = (a2 + a1) % 65521; }
