const hex = /^#[0-9a-fA-F]{6}$/.test(COR) ? COR.slice(1) : '000000';
const png = Buffer.concat([
  Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]),
  pedaco('IHDR', Buffer.concat([u32(lado), u32(lado), Buffer.from([2, 3, 0, 0, 0])])),
  pedaco('PLTE', Buffer.from('ffffff' + hex + (logo ? logo.cores.join('') : '000000000000'), 'hex')),
  pedaco('IDAT', Buffer.concat(zlib)),
  pedaco('IEND', Buffer.alloc(0)),
]);
return [{ json: { status: 200 }, binary: { data: { data: png.toString('base64'), mimeType: 'image/png', fileName: 'qr.png', fileExtension: 'png' } } }];
